window.VF2_UNITS = {"6":{"unit":6,"code":"VF2-U06","title":"THE LAW & CRIME","startNumber":89,"endNumber":113,"entries":[{"number":89,"term":"suspect sb of doing st · arrest sb for doing st · blame sb for doing st","spoken":"suspect somebody of doing something , arrest somebody for doing something , blame somebody for doing something","ipa":"suspect /səˈspɛkt/ · arrest /ɚˈɛst/ · blame /bleɪm/","type":"phrase / pattern · word family","meaning":"nghi ai đã làm gì · bắt ai vì đã làm gì · trách hoặc đổ lỗi cho ai vì đã làm gì","definition":"Suspect, arrest, and blame describe different legal or personal actions and take of or for before an -ing form.","note":"suspect sb of, arrest sb for, blame sb for: ba động từ đi với giới từ khác nhau.","example":"Police suspected the driver of hiding evidence, arrested him for dangerous driving, and blamed poor visibility for the crash."},{"number":90,"term":"accuse sb of doing st ~ charge sb with doing st","spoken":"accuse somebody of doing something , charge somebody with doing something","ipa":"accuse /əˈkjuːz/ · charge /tʃɑːrdʒ/","type":"phrase / pattern · word family","meaning":"buộc tội, cáo buộc ai đã làm gì","definition":"To formally say that somebody committed an offence; charge is the more official legal term.","note":"accuse sb of; charge sb with. charge là cáo buộc chính thức theo pháp luật hơn accuse.","example":"Prosecutors accused the company of fraud and charged two managers with falsifying records."},{"number":91,"term":"the suspect (n) # the accused (n)","spoken":"the suspect , the accused","ipa":"suspect /ˈsʌspekt/ · accused /əˈkjuːzd/","type":"noun · word family","meaning":"người bị tình nghi # bị cáo, người đã bị buộc tội","definition":"A suspect is thought to be involved; the accused has been formally charged and is facing a court.","note":"suspect là người bị tình nghi; the accused là người đã bị cáo buộc và đang chịu xét xử.","example":"The suspect was questioned by police, while the accused appeared before the court the next morning."},{"number":92,"term":"justice (n) # right (n)","spoken":"justice , right","ipa":"justice /ˈdʒʌstəs/ · right /raɪt/","type":"noun · word family","meaning":"công lí, sự công bằng # quyền","definition":"Justice is fair treatment under law; a right is something a person is legally or morally entitled to.","note":"","example":"Access to justice is a basic right, but legal support is not equally available to everyone."},{"number":93,"term":"prosecute (v) # persecute (v)","spoken":"prosecute , persecute","ipa":"prosecute /ˈprɑːsəˌkjuːt/ · persecute /ˈpɝːsəˌkjuːt/","type":"verb · word family","meaning":"truy tố hoặc khởi tố ai theo pháp luật · ngược đãi, bức hại ai dai dẳng","definition":"Prosecute means officially bring a legal case against somebody; persecute means repeatedly mistreat somebody for their identity or beliefs.","note":"prosecute là khởi tố/truy tố; đừng nhầm với persecute là ngược đãi dai dẳng vì bản sắc hoặc niềm tin.","example":"The state prosecuted the attackers for persecuting members of a religious minority."},{"number":94,"term":"persecute (v)","spoken":"persecute","ipa":"persecute /ˈpɝːsəˌkjuːt/","type":"verb","meaning":"ngược đãi ai","definition":"To treat somebody cruelly or unfairly over time, often because of identity or beliefs.","note":"","example":"The minority group was persecuted for its beliefs and forced to leave the region."},{"number":95,"term":"capital punishment (n) ~ death penalty (n) ~ death sentence (n)","spoken":"capital punishment , death penalty , death sentence","ipa":"capital /ˈkæpətəl/ · punishment /ˈpʌnɪʃmənt/ · death /dɛθ/ · penalty /ˈpɛnəlti/ · sentence /ˈsɛntəns/","type":"noun","meaning":"hình phạt tử hình theo cách nói trang trọng ~ án tử hình ~ bản án tử hình cụ thể","definition":"The legal punishment of death for a serious crime.","note":"capital punishment/death penalty là hình phạt tử hình; death sentence là bản án tử hình cụ thể.","example":"The country abolished capital punishment, so courts can no longer impose the death penalty."},{"number":96,"term":"corporal punishment","spoken":"corporal punishment","ipa":"corporal /ˈkɔːrpɚəl/ · punishment /ˈpʌnɪʃmənt/","type":"phrase / pattern","meaning":"phạt bằng đánh đập, nhục hình","definition":"Physical punishment intended to cause pain.","note":"","example":"International law prohibits corporal punishment in many educational and institutional settings."},{"number":97,"term":"burgle (v) · burglar (n) ~ thief (n) · theft (n)","spoken":"burgle , burglar , thief , theft","ipa":"burgle /ˈbɝːɡəl/ · burglar /ˈbɝːɡlɚ/ · thief /θiːf/ · theft /θɛft/","type":"verb · noun · word family","meaning":"đột nhập nhà để trộm · kẻ đột nhập nhà để trộm ~ kẻ trộm nói chung · hành vi hoặc vụ trộm","definition":"To enter a building illegally to steal; a burglar does this, while thief and theft are more general.","note":"burglar đột nhập nhà/tòa nhà để trộm; thief là kẻ trộm nói chung; theft là hành vi/vụ trộm.","example":"A burglar entered the house at night, but the thief left before taking any valuable property."},{"number":98,"term":"vandal (n)","spoken":"vandal","ipa":"vandal /ˈvændəl/","type":"noun","meaning":"kẻ phá hoại của công","definition":"A person who deliberately damages public or private property.","note":"","example":"A vandal damaged public art and was ordered to pay for the repairs."},{"number":99,"term":"sentence (v,n) · sentence sb to death · sentence sb to life","spoken":"sentence , sentence somebody to death , sentence somebody to life","ipa":"sentence /ˈsɛntəns/ · death /dɛθ/ · life /laɪf/","type":"verb · noun · phrase / pattern · word family","meaning":"kết án; bản án · kết án ai tử hình · kết án ai tù chung thân","definition":"To officially give a punishment in court, including a death or life sentence.","note":"Giữ đúng mẫu từ đi kèm: sentence (v,n) · sentence sb to death · sentence sb to life.","example":"The judge sentenced the offender to ten years in prison rather than sentencing him to life."},{"number":100,"term":"witness (v,n)","spoken":"witness","ipa":"witness /ˈwɪtnəs/","type":"verb · noun","meaning":"chứng kiến · nhân chứng","definition":"To see an event happen, or a person who gives evidence about what they saw.","note":"","example":"Two neighbours witnessed the incident and later gave evidence as witnesses."},{"number":101,"term":"on account of ~ because of # account for st","spoken":"on account of , because of , account for something","ipa":"account /əˈkaʊnt/ · because /bɪˈkɔːz/","type":"phrase / pattern · word family","meaning":"bởi vì, do · giải thích; chiếm hoặc tạo nên một phần hay tỉ lệ","definition":"On account of means because of; account for means explain something or form a particular proportion of it.","note":"on account of là bởi vì hoặc do; account for là giải thích hoặc chiếm một tỉ lệ, không đồng nghĩa trong mọi cấu trúc.","example":"The match was cancelled on account of the storm, which also accounted for most travel delays."},{"number":102,"term":"account for st ~ explain st · account for a proportion","spoken":"account for something , explain something , account for a proportion","ipa":"account /əˈkaʊnt/ · explain /ɪˈkspleɪn/ · proportion /prəˈpɔːrʃən/","type":"phrase / pattern · word family","meaning":"giải thích, lí giải điều gì ~ giải thích điều gì · chiếm hoặc tạo nên một phần/tỉ lệ","definition":"To explain the cause of something, or to form a stated proportion of a total.","note":"account for something có thể là giải thích điều gì; account for a proportion là chiếm một phần hoặc tỉ lệ","example":"Several economic factors account for the sudden rise in housing costs."},{"number":103,"term":"take st into account ~ take st into consideration","spoken":"take something into account , take something into consideration","ipa":"take /teɪk/ · into /ˈɪntu/ · account /əˈkaʊnt/ · consideration /kəˌnsɪdɚˈeɪʃən/","type":"phrase / pattern","meaning":"cân nhắc, tính đến","definition":"To consider a fact or circumstance when making a decision.","note":"Giữ đúng mẫu từ đi kèm: take st into account ~ take st into consideration.","example":"The judge took the offender's age and previous record into account before passing sentence."},{"number":104,"term":"take advantage of st ~ make use of st","spoken":"take advantage of something , make use of something","ipa":"take /teɪk/ · advantage /æˈdvæntɪdʒ/ · make /meɪk/ · use /juːs/","type":"phrase / pattern · word family","meaning":"tận dụng, sử dụng điều gì có lợi","definition":"To use an opportunity or person for benefit, sometimes unfairly.","note":"take advantage of có thể trung tính 'tận dụng' hoặc tiêu cực 'lợi dụng'; make use of thường trung tính.","example":"Some companies take advantage of legal gaps, while responsible firms make use of them only fairly."},{"number":105,"term":"mistake (v) A for B","spoken":"mistake A for B","ipa":"mistake /mɪˈsteɪk/","type":"verb · phrase / pattern","meaning":"nhầm A với B","definition":"To wrongly identify one person or thing as another.","note":"","example":"A witness mistook the second man for the suspect because they wore similar jackets."},{"number":106,"term":"glance (v,n) ~ glimpse (v,n) · catch a glimpse of sb/st","spoken":"glance , glimpse , catch a glimpse of somebody or something","ipa":"glance /ɡlæns/ · glimpse /ɡlɪmps/ · catch /kætʃ/","type":"verb · noun · phrase / pattern · word family","meaning":"liếc nhanh; cái liếc ~ thoáng thấy; cái nhìn thoáng · thoáng nhìn thấy ai hoặc điều gì","definition":"A glance is a deliberate quick look; a glimpse is a brief or accidental view.","note":"glance là chủ động nhìn nhanh; glimpse là thoáng thấy, thường tình cờ.","example":"She glanced at the screen deliberately but only caught a glimpse of the confidential message."},{"number":107,"term":"offend (v) · offence (n) · offender (n) ~ criminal (n) ~ law-breaker (n)","spoken":"offend , offence , offender , criminal , law-breaker","ipa":"offend /əˈfɛnd/ · offence /əˈfɛns/ · offender /əˈfɛndɚ/ · criminal /ˈkrɪmənəl/ · law-breaker /ˈlɔːˌbreɪkɚ/","type":"verb · noun · word family","meaning":"xúc phạm; vi phạm · hành vi vi phạm hoặc tội · người phạm tội hoặc vi phạm pháp luật","definition":"To upset or break a rule; offence is the act, and offender is the person responsible.","note":"offence là hành vi/tội; offender là người phạm; criminal thường gợi tội nghiêm trọng hơn law-breaker.","example":"The offender was charged with an offence, but not every law-breaker is a serious criminal."},{"number":108,"term":"evident (a) ~ obvious (a) ~ apparent (a) · evidence (n)","spoken":"evident , obvious , apparent , evidence","ipa":"evident /ˈɛvədənt/ · obvious /ˈɑːbviəs/ · apparent /əˈpɛrənt/ · evidence /ˈɛvədəns/","type":"noun · adjective · word family","meaning":"rõ ràng, hiển nhiên hoặc có vẻ rõ · bằng chứng","definition":"Clearly seen or understood; evidence is information that supports a conclusion.","note":"","example":"The evidence made it evident that the damage was deliberate rather than accidental."},{"number":109,"term":"bring in (a law, rule…)","spoken":"bring in (a law, rule…)","ipa":"bring /brɪŋ/","type":"phrasal verb","meaning":"ban hành luật…","definition":"To introduce a new law, rule, or system.","note":"","example":"The government brought in a new law requiring clearer online safety checks."},{"number":110,"term":"hold up ~ delay ~ put off","spoken":"hold up , delay , put off","ipa":"hold /hoʊld/ · up /ʌp/ · delay /dɪˈleɪ/ · put /pʊt/ · off /ɔːf/","type":"phrasal verb · word family","meaning":"làm chậm, gây trì hoãn ~ hoãn lại sang thời điểm khác","definition":"To delay something or make it happen later.","note":"hold up là gây chậm; put off là chủ động hoãn sang thời điểm khác.","example":"A security alert held up the train and put off the hearing until the afternoon."},{"number":111,"term":"let sb off","spoken":"let somebody off","ipa":"let /lɛt/ · off /ɔːf/","type":"phrasal verb","meaning":"thả, tha cho ai","definition":"To allow somebody to avoid punishment or a serious consequence.","note":"Giữ đúng mẫu từ đi kèm: let sb off.","example":"The judge let the teenager off with a warning because it was a first offence."},{"number":112,"term":"take sb in","spoken":"take somebody in","ipa":"take /teɪk/","type":"phrasal verb","meaning":"lừa ai","definition":"To deceive or trick somebody.","note":"Giữ đúng mẫu từ đi kèm: take sb in.","example":"The false website took several customers in by copying the bank's official design."},{"number":113,"term":"look into ~ investigate","spoken":"look into , investigate","ipa":"look /lʊk/ · into /ˈɪntu/ · investigate /ˌɪˈnvɛstəˌɡeɪt/","type":"phrasal verb · word family","meaning":"điều tra, xem xét kĩ","definition":"To investigate or examine a matter carefully.","note":"","example":"Independent investigators will look into the complaint and publish their findings."}],"pronunciationFocus":[{"entryNumber":91,"points":[{"category":"word-stress","note":"suspect /ˈsʌspekt/: khi là danh từ, trọng âm chính ở âm tiết đầu"}]},{"entryNumber":97,"points":[{"category":"common-error","note":"thief /θiːf/ và theft /θɛft/ khác cả nguyên âm lẫn âm cuối"},{"category":"final-sound","note":"theft /θɛft/: giữ rõ cụm âm cuối /ft/"}]},{"entryNumber":101,"points":[{"category":"linking","note":"account‿of: nối /t/ sang /ə/"}]},{"entryNumber":103,"points":[{"category":"word-stress","note":"consideration /kəˌnsɪdɚˈeɪʃən/: trọng âm chính đặt ở /eɪ/"}]}]}};
